"""SampleResult: what happened in one attempt (passed, failed or error), derived by the server, and why it broke;
and why a failed one failed, as one line (`derive_failure_reason`): the run's own reason, else one derived from the
facts a sample carries. That rule's SQL twin is `app/runs/samples/store/failure_reason/`; a parity test holds them
equal."""

from __future__ import annotations

import math
import re
from typing import Protocol

from probe.foundation.compat.compat import StrEnum

#: The full reward when the plan names none: a 0/1 verifier's pass mark.
DEFAULT_REWARD_MAX = 1.0


class SampleResult(StrEnum):
    """Pytest's words for one rollout. Never `status`: the SQL tool joins samples to runs (DESIGN.md)."""

    PASSED = "passed"  # a valid reward at or above the full reward
    FAILED = "failed"  # a valid reward below it (a wrong answer, or graded after a timeout)
    ERROR = "error"  # no valid reward because something broke


class SampleErrorReason(StrEnum):
    """Why an attempt broke. Each adapter maps its framework's exceptions onto these once."""

    ENGINE_ABORT = "engine_abort"  # inference engine abort or preemption
    SANDBOX = "sandbox"  # sandbox start or exec failure
    VERIFIER = "verifier"  # verifier crash, or Harbor `reward_valid = false`
    REWARD_FUNCTION = "reward_fn"  # a reward function raised
    TIMEOUT = "timeout"
    OOM = "oom"
    NETWORK = "network"
    TOOL_BACKEND = "tool_backend"  # a lost tool backend
    CANCELED = "canceled"  # someone asked (a live sample's cancel command): the attempt ended `canceled`
    PROBE_PROXY = "probe_proxy"  # the Probe rollout proxy its model calls went through stopped under it
    #: A sibling was aborted (a cancel), so the framework drops the whole group (Miles' filter): this one ended dropped.
    GROUP_HAS_ABORTED = "group_has_aborted"
    UNKNOWN = "unknown"


def derive_result(reward: float | None, *, reward_max: float = DEFAULT_REWARD_MAX,
                  error_reason: SampleErrorReason | None = None) -> SampleResult | None:
    """The red line is "was it graded": a valid reward is green or orange whatever broke around it.

    None = nothing graded it and nothing broke (an SFT example, an attempt still in flight).
    """
    if reward is not None and math.isfinite(reward):
        return SampleResult.PASSED if reward >= reward_max else SampleResult.FAILED
    if error_reason is not None or reward is not None:
        return SampleResult.ERROR
    return None

#: A run's own reason is one short line: a longer one is cut, never refused (a 422 would dead-letter its batch).
MAX_FAILURE_REASON_CHARS = 200
#: An error type as a settled row keeps it.
MAX_ERROR_TYPE_CHARS = 128


class FailureKind(StrEnum):
    """Where a reason came from. `other` is the Failures tab's bucket past the run's top 8 reasons."""

    SENT = "sent"  # the run's own `failure_reason`
    CONTEXT = "context"
    OUTPUT_LIMIT = "output_limit"
    LENGTH = "length"
    DROPPED = "dropped"
    BROKE = "broke"
    NONE = "none"
    OTHER = "other"


#: `finish_reason = length` split by the error type (its last dotted name) at the start of `error_message`. Harbor
#: files both under `engine_abort` (`connectors/harbor/samples/verdicts.py`), so this branch comes first.
LENGTH_ERROR_PREFIXES: tuple[tuple[str, FailureKind], ...] = (
    ("ContextWindowExceeded", FailureKind.CONTEXT),
    ("ContextLengthExceeded", FailureKind.CONTEXT),
    ("MaxSeqLenExceeded", FailureKind.CONTEXT),  # harbor.llms.base: "Sequence length exceeded: N > M"
    ("OutputTokenExceeded", FailureKind.OUTPUT_LIMIT),
    ("OutputLengthExceeded", FailureKind.OUTPUT_LIMIT),
)
LENGTH_PHRASES = {
    FailureKind.CONTEXT: "Ran out of context",
    FailureKind.OUTPUT_LIMIT: "Hit the output token limit",
    FailureKind.LENGTH: "Hit a length limit",
}
DROPPED_PREFIX = "Dropped: "
BROKE_PHRASES = {
    SampleErrorReason.SANDBOX: "Sandbox failed",
    SampleErrorReason.TIMEOUT: "Timed out",
    SampleErrorReason.OOM: "Ran out of memory",
    SampleErrorReason.VERIFIER: "Checker failed",
    SampleErrorReason.NETWORK: "Model API failed",
    SampleErrorReason.ENGINE_ABORT: "Inference engine aborted",
    SampleErrorReason.REWARD_FUNCTION: "Reward function failed",
    SampleErrorReason.TOOL_BACKEND: "Tool backend lost",
    SampleErrorReason.CANCELED: "Canceled",
    SampleErrorReason.PROBE_PROXY: "Probe proxy stopped",
    SampleErrorReason.GROUP_HAS_ABORTED: "Group dropped after a cancel",
    SampleErrorReason.UNKNOWN: "Broke (unknown cause)",
}
NO_REASON = "No reason recorded"
#: The Failures tab's bucket past the top 8.
OTHER_REASONS = "Other"
FAILED_RESULTS = (SampleResult.FAILED, SampleResult.ERROR)
#: The leading identifier of an error message (`litellm.ContextWindowExceededError: ...`).
ERROR_TYPE_PATTERN = r"^\s*([A-Za-z_][A-Za-z0-9_.]*)"
_ERROR_TYPE = re.compile(ERROR_TYPE_PATTERN)


def cut_failure_reason(value: object) -> object:
    """A sent reason trimmed and cut to `MAX_FAILURE_REASON_CHARS` (blank stays '', which every read takes as none).
    Non-text passes through (the field's type refuses it)."""
    return value.strip()[:MAX_FAILURE_REASON_CHARS].strip() if isinstance(value, str) else value


def get_error_type(message: str | None) -> str:
    """The error type an error message starts with, its last dotted name ('' when none)."""
    found = _ERROR_TYPE.match(message or "")
    return found.group(1).rsplit(".", 1)[-1][:MAX_ERROR_TYPE_CHARS] if found else ""


def derive_failure_reason(*, result: str | None, failure_reason: str | None, finish_reason: str | None,
                          error_type: str | None, drop_reason: str | None,
                          error_reason: str | None) -> tuple[str, FailureKind] | None:  # fmt: skip
    """The reason a failed or broken rollout failed, first match wins; None for any other result."""
    if result not in FAILED_RESULTS:
        return None
    if failure_reason:
        return failure_reason, FailureKind.SENT
    if finish_reason == "length":
        kind = next((kind for prefix, kind in LENGTH_ERROR_PREFIXES if (error_type or "").startswith(prefix)),
                    FailureKind.LENGTH)  # fmt: skip
        return LENGTH_PHRASES[kind], kind
    if drop_reason:
        return f"{DROPPED_PREFIX}{drop_reason}", FailureKind.DROPPED
    if error_reason:
        return BROKE_PHRASES.get(error_reason, BROKE_PHRASES[SampleErrorReason.UNKNOWN]), FailureKind.BROKE  # type: ignore[call-overload]
    return NO_REASON, FailureKind.NONE


class FailedSample(Protocol):
    """The fields of a whole sample the rule reads."""

    result: str | None
    failure_reason: str | None
    finish_reason: str | None
    error_message: str | None
    drop_reason: str | None
    error_reason: str | None


def derive_sample_failure_reason(sample: FailedSample) -> tuple[str, FailureKind] | None:
    """`derive_failure_reason` of a whole sample."""
    return derive_failure_reason(
        result=sample.result, failure_reason=sample.failure_reason, finish_reason=sample.finish_reason,
        error_type=get_error_type(sample.error_message), drop_reason=sample.drop_reason, error_reason=sample.error_reason,
    )  # fmt: skip
